ep(ep=130, series='ART SECRETS #2', title="Bosch's 500-year-old butt music", titlePro='Someone painted *music on a butt*',
   source='https://en.wikipedia.org/wiki/The_Garden_of_Earthly_Delights', cta={'q': 'Would you hang this at home?', 'a': 'YES', 'b': 'NO'},
   photos=[('garden', 'File:El jardín de las Delicias, de El Bosco.jpg'), ('hell', 'File:Hieronymus Bosch - The Garden of Earthly Delights - Hell.jpg'),
           ('prince', 'File:Bosch the Prince of Hell with a cauldron on his head.JPG')],
   music=('File:Rafael Krux - Fantasy Theme (cc-by) (filmmusic).mp3', 0, 0.45),
   extra_audio=[('butt', 'File:Butt Music - Hieronymus Bosch (Lute).opus', 0, 9)],
   segs=[(-1, 0, "Someone painted sheet music on a man's butt. Five hundred years ago.", 'Jemand hat Noten auf den Hintern eines Mannes gemalt. Vor fünfhundert Jahren.',
          'Alguien pintó una partitura en el trasero de un hombre. Hace quinientos años.', "Quelqu'un a peint une partition sur les fesses d'un homme. Il y a cinq cents ans.", 'Sheet music on a *butt*.'),
         (0, 0, 'This is The Garden of Earthly Delights by Hieronymus Bosch, painted between 1490 and 1510. Today it hangs in the Prado in Madrid.',
          'Das ist Der Garten der Lüste von Hieronymus Bosch, gemalt zwischen 1490 und 1510. Heute hängt er im Prado in Madrid.',
          'Esto es El jardín de las delicias, de El Bosco, pintado entre 1490 y 1510. Hoy cuelga en el Prado de Madrid.',
          "Voici Le Jardin des délices de Jérôme Bosch, peint entre 1490 et 1510. Aujourd'hui, il est au Prado, à Madrid.", 'Hieronymus *Bosch*.'),
         (1, 1, "The right panel shows hell. And in a corner known as the Musicians' Hell, sinners are tortured by giant instruments.",
          'Die rechte Tafel zeigt die Hölle. Und in einer Ecke, der Musikerhölle, werden Sünder von riesigen Instrumenten gequält.',
          'El panel derecho muestra el infierno. Y en un rincón, el infierno de los músicos, los pecadores son torturados con instrumentos gigantes.',
          "Le panneau de droite montre l'enfer. Et dans un coin, l'enfer des musiciens, des pécheurs sont torturés par des instruments géants.", "The *Musicians' Hell*."),
         (2, 0, 'One man lies trapped under a lute. And printed on his bare backside is a line of music, while a choir sings from it.',
          'Ein Mann liegt unter einer Laute gefangen. Und auf seinem nackten Hintern steht eine Notenzeile, aus der ein Chor singt.',
          'Un hombre yace atrapado bajo un laúd. Y en su trasero desnudo hay una línea de música, que un coro está cantando.',
          'Un homme est coincé sous un luth. Et sur ses fesses nues est peinte une ligne de musique, qu\'un chœur chante.', 'A line of *music*.'),
         (3, 1, 'In 2014, a student wrote those notes down and played them. The internet called it the five-hundred-year-old butt song from hell.',
          '2014 hat eine Studentin diese Noten aufgeschrieben und gespielt. Das Internet nannte es den fünfhundert Jahre alten Hintern-Song aus der Hölle.',
          'En 2014, una estudiante transcribió esas notas y las tocó. Internet lo llamó la canción del trasero del infierno, de quinientos años.',
          "En 2014, une étudiante a retranscrit ces notes et les a jouées. Internet l'a appelée la chanson des fesses de l'enfer, vieille de cinq cents ans.", 'The *butt song* from hell.'),
         (4, 0, "And this is what it sounds like.", 'Und so klingt das.', 'Y así es como suena.', 'Et voilà à quoi ça ressemble.', None),
         (5, 0, 'Bosch packed this painting with so many strange details that experts still argue about what it all means.',
          'Bosch hat so viele seltsame Details in dieses Bild gepackt, dass Experten bis heute streiten, was sie bedeuten.',
          'El Bosco llenó este cuadro de tantos detalles extraños que los expertos aún discuten qué significa todo.',
          "Bosch a mis tant de détails étranges dans ce tableau que les experts se disputent encore sur leur sens.", 'Experts still *argue*.'),
         (5, 1, 'Would you hang this painting in your living room?', 'Würdest du dieses Bild in dein Wohnzimmer hängen?',
          '¿Colgarías este cuadro en tu salón?', 'Tu accrocherais ce tableau dans ton salon ?', None)])

ep(ep=131, series='ART SECRETS #3', title="The door cut through Leonardo's Last Supper", titlePro="Someone cut a *door* through Jesus' feet",
   source='https://en.wikipedia.org/wiki/The_Last_Supper_(Leonardo)', cta={'q': 'Did you know about the door?', 'a': 'YES', 'b': 'NO'},
   photos=[('supper', 'File:The Last Supper - Leonardo Da Vinci - High Resolution 32x16.jpg'), ('room', "File:Santa Maria delle Grazie with Leonardo's The Last Supper.jpg"),
           ('detail', 'File:Cenacolo Vinciano, Santuario di Santa Maria delle Grazie, Milano (30787690786).jpg')],
   music=('File:Rafael Krux - Fantasy Theme (cc-by) (filmmusic).mp3', 30, 0.45),
   segs=[(-1, 0, "Someone cut a door through Jesus' feet. In one of the most famous paintings ever.", 'Jemand hat eine Tür durch die Füße von Jesus gebrochen. In einem der berühmtesten Bilder überhaupt.',
          'Alguien abrió una puerta a través de los pies de Jesús. En uno de los cuadros más famosos de la historia.', "Quelqu'un a percé une porte à travers les pieds de Jésus. Dans l'un des tableaux les plus célèbres.", 'A *door* through his feet.'),
         (0, 0, 'Leonardo da Vinci painted The Last Supper on the wall of a dining hall in Milan, and finished it in 1498.',
          'Leonardo da Vinci malte Das Abendmahl an die Wand eines Speisesaals in Mailand und wurde 1498 fertig.',
          'Leonardo da Vinci pintó La Última Cena en la pared de un comedor en Milán, y la terminó en 1498.',
          'Léonard de Vinci a peint La Cène sur le mur d\'un réfectoire à Milan, et l\'a terminée en 1498.', '*Leonardo*, 1498.'),
         (1, 1, 'But instead of a real fresco, he experimented with tempera on a dry wall. Soon after he finished, the paint began to flake.',
          'Aber statt eines echten Freskos experimentierte er mit Tempera auf trockener Wand. Kurz danach begann die Farbe abzublättern.',
          'Pero en lugar de un fresco auténtico, experimentó con témpera sobre una pared seca. Poco después, la pintura empezó a desprenderse.',
          "Mais au lieu d'une vraie fresque, il a expérimenté la tempera sur un mur sec. Peu après, la peinture a commencé à s'écailler.", 'The paint began to *flake*.'),
         (2, 0, 'By 1556, less than sixty years later, a writer described it as a muddle of blots.',
          'Schon 1556, keine sechzig Jahre später, beschrieb ein Autor es als Gewirr von Flecken.',
          'En 1556, menos de sesenta años después, un escritor lo describió como un revoltijo de manchas.',
          'En 1556, moins de soixante ans plus tard, un auteur le décrivait comme un fouillis de taches.', 'A *muddle of blots*.'),
         (3, 1, 'So in 1652, when the painting was barely recognizable, someone cut a doorway right through the bottom of it.',
          'Und 1652, als das Bild kaum noch zu erkennen war, brach jemand einfach eine Tür durch den unteren Teil.',
          'Así que en 1652, cuando el cuadro apenas se reconocía, alguien abrió una puerta justo en su parte de abajo.',
          "Alors en 1652, quand le tableau était à peine reconnaissable, quelqu'un a percé une porte dans sa partie basse.", 'In *1652*, a doorway.'),
         (4, 0, 'You can still see the arch today, right where Jesus\' feet used to be.',
          'Den Bogen sieht man bis heute, genau dort, wo die Füße von Jesus waren.',
          'Todavía hoy se ve el arco, justo donde estaban los pies de Jesús.',
          "On voit encore l'arc aujourd'hui, juste là où se trouvaient les pieds de Jésus.", 'Right where his *feet* were.'),
         (5, 0, 'In 1943 a bomb hit the building. Sandbags saved the wall. And a restoration that took twenty-one years finally ended in 1999.',
          '1943 traf eine Bombe das Gebäude. Sandsäcke retteten die Wand. Und eine Restaurierung von einundzwanzig Jahren endete erst 1999.',
          'En 1943 una bomba cayó sobre el edificio. Los sacos de arena salvaron el muro. Y una restauración de veintiún años terminó en 1999.',
          'En 1943, une bombe a frappé le bâtiment. Des sacs de sable ont sauvé le mur. Et une restauration de vingt et un ans s\'est achevée en 1999.', 'Saved by *sandbags*.'),
         (5, 1, 'Did you know about the door?', 'Wusstest du das mit der Tür?', '¿Sabías lo de la puerta?', 'Tu connaissais l\'histoire de la porte ?', None)])

ep(ep=132, series='ART SECRETS #4', title="The Night Watch isn't at night", titlePro="The Night Watch is *not at night*",
   source='https://en.wikipedia.org/wiki/The_Night_Watch', cta={'q': 'Did you know it was never night?', 'a': 'YES', 'b': 'NO'},
   photos=[('nw', 'File:Rembrandt - Nachtwacht - SK-C-5.jpg'), ('copy', 'File:Nachtwacht-kopie-van-voor-1712.jpg'),
           ('resto', 'File:The Night Watch undergoing restoration, on exhibit in 2024.jpg'), ('hall', 'File:Museumbezoekers in de Nachtwachtzaal enkele dagen na de heropening, HA-0028231.jpg')],
   music=('File:Rafael Krux - The Epic 2.ogg', 0, 0.42),
   segs=[(-1, 0, "The Night Watch isn't a night scene at all.", 'Die Nachtwache zeigt überhaupt keine Nacht.',
          'La ronda de noche no muestra la noche.', "La Ronde de nuit n'est pas du tout une scène de nuit.", "It's *not* a night scene."),
         (0, 0, "Rembrandt painted it in 1642: a militia company marching out, led by its captain in black.",
          'Rembrandt malte es 1642: eine Bürgerwehr beim Ausmarsch, angeführt von ihrem Hauptmann in Schwarz.',
          'Rembrandt lo pintó en 1642: una compañía de milicia saliendo en marcha, guiada por su capitán vestido de negro.',
          'Rembrandt l\'a peint en 1642 : une compagnie de milice qui se met en marche, menée par son capitaine en noir.', '*Rembrandt*, 1642.'),
         (1, 1, 'For centuries a dark varnish covered it, so people thought it showed the night. That is where the name comes from.',
          'Jahrhundertelang lag ein dunkler Firnis darauf, also dachten die Leute, es sei Nacht. Daher kommt der Name.',
          'Durante siglos lo cubrió un barniz oscuro, y la gente creyó que era de noche. De ahí viene el nombre.',
          "Pendant des siècles, un vernis sombre le recouvrait, alors on a cru que c'était la nuit. D'où son nom.", 'A dark *varnish*.'),
         (2, 0, "And it's not even complete. In 1715 it was moved to Amsterdam's town hall, and trimmed on all four sides to fit.",
          'Und es ist nicht mal vollständig. 1715 kam es ins Amsterdamer Rathaus und wurde an allen vier Seiten beschnitten, damit es passt.',
          'Y ni siquiera está completo. En 1715 lo llevaron al ayuntamiento de Ámsterdam y lo recortaron por los cuatro lados para que cupiera.',
          "Et il n'est même pas complet. En 1715, on l'a installé à l'hôtel de ville d'Amsterdam, et on l'a coupé sur les quatre côtés.", 'Trimmed on *all four sides*.'),
         (3, 0, 'An old copy shows what is missing, including figures on the left. The cut pieces have never been found.',
          'Eine alte Kopie zeigt, was fehlt, auch Figuren auf der linken Seite. Die abgeschnittenen Teile wurden nie gefunden.',
          'Una copia antigua muestra lo que falta, incluidas figuras a la izquierda. Los trozos cortados nunca aparecieron.',
          'Une ancienne copie montre ce qui manque, dont des personnages à gauche. Les morceaux coupés n\'ont jamais été retrouvés.', '*Never* been found.'),
         (4, 1, 'That thick varnish did help once. In 1911, a man attacked the painting with a knife, and the coating protected it.',
          'Einmal hat der dicke Firnis sogar geholfen. 1911 griff ein Mann das Bild mit einem Messer an, und die Schicht schützte es.',
          'Ese barniz grueso sí ayudó una vez. En 1911, un hombre atacó el cuadro con un cuchillo, y la capa lo protegió.',
          "Ce vernis épais l'a pourtant sauvé une fois. En 1911, un homme l'a attaqué au couteau, et la couche l'a protégé.", 'Attacked with a *knife*.'),
         (5, 0, 'Today it hangs in the Rijksmuseum, where it is being restored in a glass room, right in front of visitors.',
          'Heute hängt es im Rijksmuseum und wird in einem Glasraum restauriert, direkt vor den Augen der Besucher.',
          'Hoy cuelga en el Rijksmuseum, donde lo restauran en una sala de cristal, delante de los visitantes.',
          "Aujourd'hui, il est au Rijksmuseum, restauré dans une cage de verre, devant les visiteurs.", 'In front of *visitors*.'),
         (5, 1, 'Did you know it was never night?', 'Wusstest du, dass es nie Nacht war?', '¿Sabías que nunca fue de noche?', 'Tu savais que ce n\'était pas la nuit ?', None)])

